		$faq = array( array( '@type' => 'Question', 'name' => '01Will we have access to our ad accounts, analytics, and dashboards?', 'acceptedAnswer' => array( '@type' => 'Answer', 'text' => 'Yes. Your ad accounts, analytics properties and reporting dashboards stay in your ownership, and we work inside them with the access you grant. You can review campaigns, spend and results at any time. Nothing is hidden behind agency-only tools.' ) ), array( '@type' => 'Question', 'name' => '02How do you improve ROAS without reducing lead quality or sales volume?', 'acceptedAnswer' => array( '@type' => 'Answer', 'text' => 'We improve returns by working on the whole funnel, not just cheaper clicks. That means sharper audience targeting, stronger creatives and landing pages, bid and budget adjustments based on conversion data, and, where available, CRM or sales feedback so we scale what brings qualified leads and sales, not just volume.' ) ), array( '@type' => 'Question', 'name' => '03What reporting will we receive from your agency?', 'acceptedAnswer' => array( '@type' => 'Answer', 'text' => 'You receive clear reports on campaign performance, advertising spend and areas for improvement, covering metrics such as clicks, CTR, CPC, conversions, cost per lead and ROAS where relevant. Each report ends with what we learned and what we plan to test next.' ) ), array( '@type' => 'Question', 'name' => '04Can you take over an existing performance marketing account?', 'acceptedAnswer' => array( '@type' => 'Answer', 'text' => 'Yes. We begin with an audit of your current account structure, tracking, audiences, creatives and spend, identify what is working and what is wasting budget, and then build an improvement plan, without starting from scratch unless that is genuinely the better option.' ) ), array( '@type' => 'Question', 'name' => '05Can I run campaigns across multiple performance marketing channels at the same time?', 'acceptedAnswer' => array( '@type' => 'Answer', 'text' => 'Yes, and often it works best that way. We plan the budget across channels such as Google Search, YouTube, Meta and LinkedIn according to your goals and audience, track each one consistently, and shift spend towards the channels that perform.' ) ), array( '@type' => 'Question', 'name' => '06Can you generate qualified B2B leads through performance marketing?', 'acceptedAnswer' => array( '@type' => 'Answer', 'text' => 'Yes. We use professional audience targeting on LinkedIn and Google, pair it with focused offers and landing pages, and track enquiries and demo requests through to lead quality, so the focus stays on qualified leads, not just form fills.' ) ) );
		$ld  = array(
			'@context'   => 'https://schema.org',
			'@type'      => 'FAQPage',
			'mainEntity' => $faq,
		);
		echo '<script type="application/ld+json">' . wp_json_encode( $ld, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES ) . '</script>' . "\n";
	},
	5
);
